// SPDX-License-Identifier: AGPL-3.0-or-later AND LicenseRef-Commercial

//! Diagnostic → DiagnosticEntry conversion.
//!
//! Bridges the analyzer's rich `Diagnostic` type to the manifest's
//! `DiagnosticEntry` type for output formatting. Every field is mapped
//! with no information loss.

use crate::analyzer::diagnostic::{Diagnostic, Evidence};
use crate::manifest::types::{DiagnosticEntry, EvidenceEntry};

/// Converts a single `Diagnostic` to a manifest-ready `DiagnosticEntry`.
///
/// Field mapping:
/// - `pattern` → `DiagnosticPattern.name()` (snake_case)
/// - `severity` → lowercase Display string
/// - `confidence` → lowercase Display string
/// - `evidence` → `Vec<EvidenceEntry>` with per-observation location and context
/// - `location` → `loc` (field rename)
pub fn to_manifest_entry(diagnostic: &Diagnostic) -> DiagnosticEntry {
    DiagnosticEntry {
        id: diagnostic.id.clone(),
        pattern: diagnostic.pattern.name().to_string(),
        severity: diagnostic.severity.to_string(),
        confidence: diagnostic.confidence.to_string(),
        entity: diagnostic.entity.clone(),
        message: diagnostic.message.clone(),
        evidence: convert_evidence(&diagnostic.evidence),
        suggestion: diagnostic.suggestion.clone(),
        loc: diagnostic.location.clone(),
    }
}

/// Converts a slice of `Diagnostic`s to manifest-ready `DiagnosticEntry`s.
pub fn to_manifest_entries(diagnostics: &[Diagnostic]) -> Vec<DiagnosticEntry> {
    diagnostics.iter().map(to_manifest_entry).collect()
}

/// Converts analyzer evidence entries to manifest evidence entries.
///
/// Maps `analyzer::diagnostic::Evidence` to `manifest::types::EvidenceEntry`
/// preserving all structured fields (observation, location, context).
fn convert_evidence(evidence: &[Evidence]) -> Vec<EvidenceEntry> {
    evidence
        .iter()
        .map(|e| EvidenceEntry {
            observation: e.observation.clone(),
            location: e.location.clone(),
            context: e.context.clone(),
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::analyzer::diagnostic::*;

    fn make_diagnostic(
        pattern: DiagnosticPattern,
        severity: Severity,
        confidence: Confidence,
    ) -> Diagnostic {
        Diagnostic {
            id: "D001".to_string(),
            pattern,
            severity,
            confidence,
            entity: "mod::fn".to_string(),
            message: "Test diagnostic message".to_string(),
            evidence: vec![Evidence {
                observation: "0 callers in 5 files".to_string(),
                location: Some("a.py:10".to_string()),
                context: Some("private".to_string()),
            }],
            suggestion: "Remove the function or add a caller.".to_string(),
            location: "file.py:10".to_string(),
        }
    }

    // -- 1.1 Full field conversion --

    #[test]
    fn test_conversion_preserves_all_fields() {
        let diag = make_diagnostic(
            DiagnosticPattern::DataDeadEnd,
            Severity::Warning,
            Confidence::High,
        );
        let entry = to_manifest_entry(&diag);

        assert_eq!(entry.id, "D001");
        assert_eq!(entry.pattern, "data_dead_end");
        assert_eq!(entry.severity, "warning");
        assert_eq!(entry.confidence, "high");
        assert_eq!(entry.entity, "mod::fn");
        assert_eq!(entry.message, "Test diagnostic message");
        assert_eq!(entry.suggestion, "Remove the function or add a caller.");
        assert_eq!(entry.loc, "file.py:10");
        // Evidence is structured Vec<EvidenceEntry>
        assert_eq!(entry.evidence.len(), 1);
        assert_eq!(entry.evidence[0].observation, "0 callers in 5 files");
        assert_eq!(entry.evidence[0].location, Some("a.py:10".to_string()));
        assert_eq!(entry.evidence[0].context, Some("private".to_string()));
    }

    // -- 1.2 Multi-evidence conversion --

    #[test]
    fn test_conversion_preserves_multi_evidence() {
        let diag = Diagnostic {
            id: "D002".to_string(),
            pattern: DiagnosticPattern::IsolatedCluster,
            severity: Severity::Warning,
            confidence: Confidence::High,
            entity: "cluster".to_string(),
            message: "Isolated cluster found".to_string(),
            evidence: vec![
                Evidence {
                    observation: "0 callers in 5 files".to_string(),
                    location: Some("a.py:10".to_string()),
                    context: Some("private".to_string()),
                },
                Evidence {
                    observation: "defined but unused".to_string(),
                    location: None,
                    context: None,
                },
                Evidence {
                    observation: "cluster of 3".to_string(),
                    location: Some("b.py:1".to_string()),
                    context: Some("isolated".to_string()),
                },
            ],
            suggestion: "Wire this module.".to_string(),
            location: "module.py:1".to_string(),
        };
        let entry = to_manifest_entry(&diag);

        // All three evidence entries should be present
        assert_eq!(entry.evidence.len(), 3);
        assert_eq!(entry.evidence[0].observation, "0 callers in 5 files");
        assert_eq!(entry.evidence[0].location, Some("a.py:10".to_string()));
        assert_eq!(entry.evidence[1].observation, "defined but unused");
        assert_eq!(entry.evidence[1].location, None);
        assert_eq!(entry.evidence[2].observation, "cluster of 3");
        assert_eq!(entry.evidence[2].location, Some("b.py:1".to_string()));
    }

    // -- 1.3 Severity display --

    #[test]
    fn test_severity_display_all_variants_lowercase() {
        assert_eq!(format!("{}", Severity::Info), "info");
        assert_eq!(format!("{}", Severity::Warning), "warning");
        assert_eq!(format!("{}", Severity::Critical), "critical");
    }

    #[test]
    fn test_severity_display_roundtrip_with_from_str() {
        for sev in [Severity::Info, Severity::Warning, Severity::Critical] {
            let s = format!("{}", sev);
            assert_eq!(
                Severity::from_str_checked(&s),
                Some(sev),
                "Display output must round-trip through from_str_checked"
            );
        }
    }

    // -- 1.4 Confidence display --

    #[test]
    fn test_confidence_display_all_variants_lowercase() {
        assert_eq!(format!("{}", Confidence::Low), "low");
        assert_eq!(format!("{}", Confidence::Moderate), "moderate");
        assert_eq!(format!("{}", Confidence::High), "high");
    }

    #[test]
    fn test_confidence_display_roundtrip_with_from_str() {
        for conf in [Confidence::Low, Confidence::Moderate, Confidence::High] {
            let s = format!("{}", conf);
            assert_eq!(
                Confidence::from_str_checked(&s),
                Some(conf),
                "Display output must round-trip through from_str_checked"
            );
        }
    }

    // -- 1.5 All 13 pattern names convert --

    #[test]
    fn test_conversion_handles_all_13_pattern_variants() {
        let patterns = vec![
            DiagnosticPattern::IsolatedCluster,
            DiagnosticPattern::DataDeadEnd,
            DiagnosticPattern::PartialWiring,
            DiagnosticPattern::OrphanedImplementation,
            DiagnosticPattern::Duplication,
            DiagnosticPattern::ContractMismatch,
            DiagnosticPattern::CircularDependency,
            DiagnosticPattern::LayerViolation,
            DiagnosticPattern::IncompleteMigration,
            DiagnosticPattern::AsymmetricHandling,
            DiagnosticPattern::StaleReference,
            DiagnosticPattern::PhantomDependency,
            DiagnosticPattern::MissingReexport,
        ];
        for pattern in patterns {
            let diag = Diagnostic {
                id: "D999".into(),
                pattern,
                severity: Severity::Info,
                confidence: Confidence::Low,
                entity: "test".into(),
                message: "test".into(),
                evidence: vec![Evidence {
                    observation: "test".into(),
                    location: None,
                    context: None,
                }],
                suggestion: "test".into(),
                location: "test.py:1".into(),
            };
            let entry = to_manifest_entry(&diag);
            assert_eq!(
                entry.pattern,
                pattern.name(),
                "Pattern {:?} should convert to '{}'",
                pattern,
                pattern.name()
            );
        }
    }

    // -- 1.6 Empty evidence --

    #[test]
    fn test_conversion_handles_empty_evidence() {
        let diag = Diagnostic {
            id: "D001".into(),
            pattern: DiagnosticPattern::DataDeadEnd,
            severity: Severity::Warning,
            confidence: Confidence::High,
            entity: "test".into(),
            message: "test".into(),
            evidence: vec![],
            suggestion: "test".into(),
            location: "test.py:1".into(),
        };
        let entry = to_manifest_entry(&diag);
        assert!(
            entry.evidence.is_empty(),
            "Empty evidence Vec should produce empty Vec"
        );
    }

    // -- 1.7 Round-trip YAML --

    #[test]
    fn test_conversion_to_yaml_roundtrip() {
        let diag = make_diagnostic(
            DiagnosticPattern::PhantomDependency,
            Severity::Info,
            Confidence::High,
        );
        let entry = to_manifest_entry(&diag);

        let yaml = serde_yaml::to_string(&entry).expect("serialize to YAML");
        let roundtripped: DiagnosticEntry =
            serde_yaml::from_str(&yaml).expect("deserialize from YAML");

        assert_eq!(entry.id, roundtripped.id);
        assert_eq!(entry.pattern, roundtripped.pattern);
        assert_eq!(entry.severity, roundtripped.severity);
        assert_eq!(entry.confidence, roundtripped.confidence);
        assert_eq!(entry.entity, roundtripped.entity);
        assert_eq!(entry.message, roundtripped.message);
        assert_eq!(entry.evidence, roundtripped.evidence);
        assert_eq!(entry.suggestion, roundtripped.suggestion);
        assert_eq!(entry.loc, roundtripped.loc);
    }

    // -- Batch conversion --

    #[test]
    fn test_to_manifest_entries_batch_conversion() {
        let diags = vec![
            make_diagnostic(
                DiagnosticPattern::DataDeadEnd,
                Severity::Warning,
                Confidence::High,
            ),
            make_diagnostic(
                DiagnosticPattern::IsolatedCluster,
                Severity::Warning,
                Confidence::Moderate,
            ),
        ];
        let entries = to_manifest_entries(&diags);
        assert_eq!(entries.len(), 2);
        assert_eq!(entries[0].pattern, "data_dead_end");
        assert_eq!(entries[1].pattern, "isolated_cluster");
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later AND LicenseRef-Commercial

//! Diagnostic types — the output of every analyzer function.
//!
//! Every diagnostic carries a pattern, severity, confidence, evidence,
//! and an actionable suggestion. Evidence must be concrete (specific
//! file:line, counts, observations) — never vague.

use serde::{Deserialize, Serialize};

/// A diagnostic finding produced by a pattern detector.
///
/// Every field is mandatory. Diagnostics with missing evidence or vague
/// suggestions are considered broken. The `id` field is assigned by the
/// pattern registry when collecting results, not by individual detectors.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Diagnostic {
    /// Unique ID assigned by the registry (e.g., "D001", "D002").
    pub id: String,
    /// Which of the 13 diagnostic patterns this finding belongs to.
    pub pattern: DiagnosticPattern,
    /// How severe the issue is.
    pub severity: Severity,
    /// How confident Flowspec is in this finding.
    pub confidence: Confidence,
    /// Primary entity or entities involved (symbol names).
    pub entity: String,
    /// Human/agent-readable description using failure-pattern language.
    pub message: String,
    /// Concrete proof of what Flowspec observed.
    pub evidence: Vec<Evidence>,
    /// Actionable fix suggestion.
    pub suggestion: String,
    /// Primary source location (file:line format).
    pub location: String,
}

/// A single piece of evidence supporting a diagnostic.
///
/// Evidence is always concrete — "0 callers in 15 analyzed files",
/// not "might be unused". Location and context are optional because
/// some evidence is about groups of symbols, not a single location.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Evidence {
    /// What Flowspec observed: counts, structural facts, specific findings.
    pub observation: String,
    /// Source location if applicable (file:line format).
    pub location: Option<String>,
    /// Additional context explaining the observation.
    pub context: Option<String>,
}

/// The 13 diagnostic patterns organized by failure pattern.
///
/// All 13 variants are defined for a stable contract even when only
/// some are implemented. The pattern registry uses this enum for
/// `--checks` filtering in the CLI.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum DiagnosticPattern {
    /// Connected components with zero inbound external edges.
    IsolatedCluster,
    /// Symbols defined but never consumed.
    DataDeadEnd,
    /// Error handlers on some paths but not parallel ones.
    PartialWiring,
    /// Trait impls with no dispatch points, public methods with zero callers.
    OrphanedImplementation,
    /// Structural similarity in IR (not textual).
    Duplication,
    /// Serde annotations vs. API schemas, signatures vs. call sites.
    ContractMismatch,
    /// Cycles in the module dependency graph.
    CircularDependency,
    /// Cross-module references violating user-defined rules.
    LayerViolation,
    /// Old/new patterns coexisting with split callers.
    IncompleteMigration,
    /// Parallel functions with inconsistent treatment.
    AsymmetricHandling,
    /// Imports resolving to re-exports/shims/moved definitions.
    StaleReference,
    /// Imports where zero imported symbols are referenced downstream.
    PhantomDependency,
    /// Public symbols not re-exported through parent module.
    MissingReexport,
}

/// Severity level of a diagnostic finding.
///
/// Ordering: Info < Warning < Critical. This ordering is used by the
/// `--severity` CLI filter: `--severity warning` means "warning and above".
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub enum Severity {
    /// Informational — suboptimal but not broken.
    Info,
    /// Warning — structural defect that will cause problems.
    Warning,
    /// Critical — breaks correctness or causes data loss.
    Critical,
}

/// Confidence level of a diagnostic finding.
///
/// Ordering: Low < Moderate < High. This ordering is used by the
/// `--confidence` CLI filter. High confidence means structural proof
/// exists. Low confidence means the finding might be a false positive.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub enum Confidence {
    /// Low — may be a false positive (e.g., public function with zero internal callers).
    Low,
    /// Moderate — likely a real issue, warrants investigation.
    Moderate,
    /// High — structural proof exists (e.g., private function with zero callers).
    High,
}

impl std::fmt::Display for Severity {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Severity::Info => write!(f, "info"),
            Severity::Warning => write!(f, "warning"),
            Severity::Critical => write!(f, "critical"),
        }
    }
}

impl Severity {
    /// Parse a severity string (for CLI filter compatibility).
    pub fn from_str_checked(s: &str) -> Option<Self> {
        match s {
            "critical" => Some(Severity::Critical),
            "warning" => Some(Severity::Warning),
            "info" => Some(Severity::Info),
            _ => None,
        }
    }
}

impl std::fmt::Display for Confidence {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Confidence::Low => write!(f, "low"),
            Confidence::Moderate => write!(f, "moderate"),
            Confidence::High => write!(f, "high"),
        }
    }
}

impl Confidence {
    /// Parse a confidence string (for CLI filter compatibility).
    pub fn from_str_checked(s: &str) -> Option<Self> {
        match s {
            "high" => Some(Confidence::High),
            "moderate" => Some(Confidence::Moderate),
            "low" => Some(Confidence::Low),
            _ => None,
        }
    }
}

impl DiagnosticPattern {
    /// Returns the snake_case name of this pattern (for --checks filtering).
    pub fn name(&self) -> &'static str {
        match self {
            Self::IsolatedCluster => "isolated_cluster",
            Self::DataDeadEnd => "data_dead_end",
            Self::PartialWiring => "partial_wiring",
            Self::OrphanedImplementation => "orphaned_impl",
            Self::Duplication => "duplication",
            Self::ContractMismatch => "contract_mismatch",
            Self::CircularDependency => "circular_dependency",
            Self::LayerViolation => "layer_violation",
            Self::IncompleteMigration => "incomplete_migration",
            Self::AsymmetricHandling => "asymmetric_handling",
            Self::StaleReference => "stale_reference",
            Self::PhantomDependency => "phantom_dependency",
            Self::MissingReexport => "missing_reexport",
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    // -- Diagnostic construction -----------------------------------------------

    #[test]
    fn test_diagnostic_construction_all_fields_populated() {
        let d = Diagnostic {
            id: "D001".to_string(),
            pattern: DiagnosticPattern::DataDeadEnd,
            severity: Severity::Warning,
            confidence: Confidence::High,
            entity: "module::unused_fn".to_string(),
            message: "Function unused_fn is never called".to_string(),
            evidence: vec![Evidence {
                observation: "0 callers in 5 analyzed files".to_string(),
                location: Some("src/utils.py:42".to_string()),
                context: Some("function is private".to_string()),
            }],
            suggestion: "Remove the function or add a caller.".to_string(),
            location: "src/utils.py:42".to_string(),
        };
        assert_eq!(d.id, "D001");
        assert_eq!(d.pattern, DiagnosticPattern::DataDeadEnd);
        assert_eq!(d.severity, Severity::Warning);
        assert_eq!(d.confidence, Confidence::High);
        assert!(!d.entity.is_empty());
        assert!(!d.message.is_empty());
        assert!(!d.evidence.is_empty());
        assert!(!d.suggestion.is_empty());
        assert!(!d.location.is_empty());
    }

    #[test]
    fn test_diagnostic_evidence_is_vec_not_empty() {
        let d = Diagnostic {
            id: String::new(),
            pattern: DiagnosticPattern::IsolatedCluster,
            severity: Severity::Warning,
            confidence: Confidence::High,
            entity: "cluster".to_string(),
            message: "Isolated cluster found".to_string(),
            evidence: vec![
                Evidence {
                    observation: "0 external callers".to_string(),
                    location: None,
                    context: None,
                },
                Evidence {
                    observation: "3 internal references".to_string(),
                    location: None,
                    context: None,
                },
                Evidence {
                    observation: "cluster contains: A, B, C".to_string(),
                    location: None,
                    context: None,
                },
            ],
            suggestion: "Wire this module into the rest of the codebase.".to_string(),
            location: "module.py:1".to_string(),
        };
        assert_eq!(d.evidence.len(), 3);
        for ev in &d.evidence {
            assert!(!ev.observation.is_empty());
        }
    }

    #[test]
    fn test_diagnostic_serialization_roundtrip() {
        let d = Diagnostic {
            id: "D042".to_string(),
            pattern: DiagnosticPattern::PhantomDependency,
            severity: Severity::Info,
            confidence: Confidence::High,
            entity: "os".to_string(),
            message: "Import 'os' is never used".to_string(),
            evidence: vec![Evidence {
                observation: "0 references in file".to_string(),
                location: Some("main.py:1".to_string()),
                context: None,
            }],
            suggestion: "Remove the unused import.".to_string(),
            location: "main.py:1".to_string(),
        };
        let yaml = serde_yaml::to_string(&d).expect("serialize");
        let roundtripped: Diagnostic = serde_yaml::from_str(&yaml).expect("deserialize");
        assert_eq!(d, roundtripped);
    }

    // -- Enum ordering ---------------------------------------------------------

    #[test]
    fn test_severity_ordering_critical_gt_warning_gt_info() {
        assert!(Severity::Critical > Severity::Warning);
        assert!(Severity::Warning > Severity::Info);
        assert!(Severity::Critical > Severity::Info);
    }

    #[test]
    fn test_confidence_ordering_high_gt_moderate_gt_low() {
        assert!(Confidence::High > Confidence::Moderate);
        assert!(Confidence::Moderate > Confidence::Low);
        assert!(Confidence::High > Confidence::Low);
    }

    // -- DiagnosticPattern completeness ----------------------------------------

    #[test]
    fn test_diagnostic_pattern_has_all_13_variants() {
        let variants = vec![
            DiagnosticPattern::IsolatedCluster,
            DiagnosticPattern::DataDeadEnd,
            DiagnosticPattern::PartialWiring,
            DiagnosticPattern::OrphanedImplementation,
            DiagnosticPattern::Duplication,
            DiagnosticPattern::ContractMismatch,
            DiagnosticPattern::CircularDependency,
            DiagnosticPattern::LayerViolation,
            DiagnosticPattern::IncompleteMigration,
            DiagnosticPattern::AsymmetricHandling,
            DiagnosticPattern::StaleReference,
            DiagnosticPattern::PhantomDependency,
            DiagnosticPattern::MissingReexport,
        ];
        assert_eq!(variants.len(), 13);
    }

    // -- Evidence construction -------------------------------------------------

    #[test]
    fn test_evidence_with_location_and_context() {
        let ev = Evidence {
            observation: "0 callers in 15 analyzed files".to_string(),
            location: Some("src/utils.py:42".to_string()),
            context: Some("function is pub".to_string()),
        };
        assert!(!ev.observation.is_empty());
        assert!(ev.location.is_some());
        assert!(ev.context.is_some());
    }

    #[test]
    fn test_evidence_with_observation_only() {
        let ev = Evidence {
            observation: "module has 3 internal references".to_string(),
            location: None,
            context: None,
        };
        assert!(!ev.observation.is_empty());
        assert!(ev.location.is_none());
        assert!(ev.context.is_none());
    }

    // -- from_str_checked methods ----------------------------------------------

    #[test]
    fn test_severity_from_str_checked() {
        assert_eq!(
            Severity::from_str_checked("critical"),
            Some(Severity::Critical)
        );
        assert_eq!(
            Severity::from_str_checked("warning"),
            Some(Severity::Warning)
        );
        assert_eq!(Severity::from_str_checked("info"), Some(Severity::Info));
        assert_eq!(Severity::from_str_checked("unknown"), None);
    }

    #[test]
    fn test_confidence_from_str_checked() {
        assert_eq!(Confidence::from_str_checked("high"), Some(Confidence::High));
        assert_eq!(
            Confidence::from_str_checked("moderate"),
            Some(Confidence::Moderate)
        );
        assert_eq!(Confidence::from_str_checked("low"), Some(Confidence::Low));
        assert_eq!(Confidence::from_str_checked("unknown"), None);
    }
}

// SPDX-License-Identifier: AGPL-3.0-or-later AND LicenseRef-Commercial

//! Entity data extraction from the analysis graph.
//!
//! Standalone query functions that extract manifest-ready data from a
//! populated Graph. These replace the hardcoded placeholders from cycle 1's
//! text scanner (`vis: "pub"`, `called_by: ["(detected)"]`).

use std::collections::HashMap;
use std::path::Path;

use serde::{Deserialize, Serialize};

use crate::graph::Graph;
use crate::parser::ir::{Symbol, SymbolId, SymbolKind, Visibility};

/// Direction of a module-level dependency edge.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum DependencyDirection {
    /// Only one module references the other.
    Unidirectional,
    /// Both modules reference each other.
    Bidirectional,
}

/// A module-level dependency edge for the manifest's `dependency_graph` section.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ModuleDependency {
    /// Source module file path.
    pub from: String,
    /// Target module file path.
    pub to: String,
    /// Number of cross-file references.
    pub weight: usize,
    /// Whether the dependency is unidirectional or bidirectional.
    pub direction: DependencyDirection,
    /// Related diagnostic IDs (e.g., circular dependency findings).
    pub issues: Vec<String>,
}

/// Extracts module-level dependency edges from cross-file references in the graph.
///
/// Walks all symbols, checks outgoing edges for cross-file targets, and aggregates
/// by file pair. Bidirectional edges (A→B and B→A both exist) are merged into a
/// single entry with combined weight. The `from` field gets the lexicographically
/// smaller path for deterministic ordering.
pub fn extract_dependency_graph(graph: &Graph) -> Vec<ModuleDependency> {
    // Count cross-file edges per (source_file, target_file) pair
    let mut edge_counts: HashMap<(String, String), usize> = HashMap::new();

    for (sym_id, symbol) in graph.all_symbols() {
        let source_file = symbol.location.file.to_string_lossy().to_string();

        for edge in graph.edges_from(sym_id) {
            // Skip unresolved edges (SymbolId::default())
            if edge.target == SymbolId::default() {
                continue;
            }

            if let Some(target_sym) = graph.get_symbol(edge.target) {
                let target_file = target_sym.location.file.to_string_lossy().to_string();

                // Only count cross-file edges
                if source_file != target_file {
                    *edge_counts
                        .entry((source_file.clone(), target_file))
                        .or_insert(0) += 1;
                }
            }
        }
    }

    // Merge bidirectional edges: if both (A→B) and (B→A) exist, combine them
    let mut merged: HashMap<(String, String), ModuleDependency> = HashMap::new();

    for ((from, to), count) in edge_counts {
        // Canonical key: lexicographically smaller path first
        let (canonical_from, canonical_to) = if from <= to {
            (from.clone(), to.clone())
        } else {
            (to.clone(), from.clone())
        };

        let key = (canonical_from.clone(), canonical_to.clone());

        let entry = merged.entry(key).or_insert_with(|| ModuleDependency {
            from: canonical_from,
            to: canonical_to,
            weight: 0,
            direction: DependencyDirection::Unidirectional,
            issues: vec![],
        });

        entry.weight += count;

        // If the original (from, to) doesn't match canonical order,
        // it means we have a reverse edge → bidirectional
        if from > to {
            entry.direction = DependencyDirection::Bidirectional;
        }
    }

    let mut result: Vec<ModuleDependency> = merged.into_values().collect();
    result.sort_by(|a, b| a.from.cmp(&b.from).then(a.to.cmp(&b.to)));
    result
}

/// Extracts the qualified names of all symbols called by the given symbol.
///
/// Uses `graph.callees()` which returns outgoing edges with `EdgeKind::Calls`.
/// Filters `SymbolId::default()` phantom entries (unresolved cross-file
/// references) and symbols whose IDs cannot be resolved (defensive).
pub fn extract_calls(graph: &Graph, symbol_id: SymbolId) -> Vec<String> {
    graph
        .callees(symbol_id)
        .iter()
        .filter(|&&callee_id| callee_id != SymbolId::default())
        .filter_map(|&callee_id| {
            graph
                .get_symbol(callee_id)
                .map(|s| s.qualified_name.clone())
        })
        .collect()
}

/// Extracts the qualified names of all symbols that call the given symbol.
///
/// Uses `graph.callers()` which returns incoming edges with `EdgeKind::Calls`.
/// Filters `SymbolId::default()` phantom entries (unresolved cross-file
/// references) and symbols whose IDs cannot be resolved (defensive).
pub fn extract_called_by(graph: &Graph, symbol_id: SymbolId) -> Vec<String> {
    graph
        .callers(symbol_id)
        .iter()
        .filter(|&&caller_id| caller_id != SymbolId::default())
        .filter_map(|&caller_id| {
            graph
                .get_symbol(caller_id)
                .map(|s| s.qualified_name.clone())
        })
        .collect()
}

/// Extracts a manifest-ready visibility string from a Symbol.
///
/// Mapping:
/// - `Public` → `"pub"`
/// - `Private` → `"priv"`
/// - `Crate` → `"crate"`
/// - `Protected` → `"protected"`
pub fn extract_visibility(symbol: &Symbol) -> String {
    match symbol.visibility {
        Visibility::Public => "pub".to_string(),
        Visibility::Private => "priv".to_string(),
        Visibility::Crate => "crate".to_string(),
        Visibility::Protected => "protected".to_string(),
    }
}

/// Infers a meaningful role description for a module based on its symbols.
///
/// Heuristics (checked in priority order):
/// 1. Has `main` or `__main__` → "Entry point module"
/// 2. Test file or test functions → "Test module"
/// 3. Mostly classes/structs → "Data model module"
/// 4. Has import re-exports → "API boundary module"
/// 5. Mostly functions → "Utility module"
/// 6. Mixed → "Service module"
/// 7. Empty → "Empty module"
pub fn infer_module_role(graph: &Graph, file_path: &Path) -> String {
    let symbol_ids = graph.symbols_in_file(file_path);

    if symbol_ids.is_empty() {
        return "Empty module".to_string();
    }

    let symbols: Vec<&Symbol> = symbol_ids
        .iter()
        .filter_map(|&id| graph.get_symbol(id))
        .collect();

    if symbols.is_empty() {
        return "Empty module".to_string();
    }

    // Check for entry point
    let has_main = symbols.iter().any(|s| {
        s.name == "main"
            || s.name == "__main__"
            || s.annotations.contains(&"entry_point".to_string())
    });
    if has_main {
        return "Entry point module".to_string();
    }

    // Check for test module (by file path or function names)
    let file_str = file_path.to_string_lossy();
    let is_test_file = crate::analyzer::patterns::exclusion::is_test_path(&file_str);
    let test_fn_count = symbols
        .iter()
        .filter(|s| {
            s.name.starts_with("test_")
                && (s.kind == SymbolKind::Function || s.kind == SymbolKind::Method)
        })
        .count();
    if is_test_file || test_fn_count > 0 {
        return "Test module".to_string();
    }

    // Count symbol kinds (exclude Module and Method symbols from counts).
    // Methods belong to classes and should not dilute the class ratio.
    let non_module_symbols: Vec<&&Symbol> = symbols
        .iter()
        .filter(|s| s.kind != SymbolKind::Module && s.kind != SymbolKind::Method)
        .collect();

    if non_module_symbols.is_empty() {
        return "Empty module".to_string();
    }

    let class_count = non_module_symbols
        .iter()
        .filter(|s| {
            matches!(
                s.kind,
                SymbolKind::Class | SymbolKind::Struct | SymbolKind::Enum
            )
        })
        .count();

    let fn_count = non_module_symbols
        .iter()
        .filter(|s| s.kind == SymbolKind::Function)
        .count();

    let import_count = non_module_symbols
        .iter()
        .filter(|s| s.annotations.contains(&"import".to_string()))
        .count();

    let total = non_module_symbols.len();

    // Mostly classes → data model
    if class_count > 0 && class_count * 2 >= total {
        return "Data model module".to_string();
    }

    // Mostly imports → API boundary
    if import_count > 0 && import_count * 2 >= total {
        return "API boundary module".to_string();
    }

    // Mostly functions → utility
    if fn_count > 0 && fn_count * 2 >= total {
        return "Utility module".to_string();
    }

    // Mix of things
    "Service module".to_string()
}

