    #[test]
    fn test_circular_dependency_detects_multiple_independent_cycles() {
        let mut graph = Graph::new();

        // Cycle 1: A <-> B
        let a = graph.add_symbol(make_symbol(
            "func_a",
            crate::parser::ir::SymbolKind::Function,
            crate::parser::ir::Visibility::Public,
            "mod_a.py",
