            .unwrap();
        assert_eq!(d.pattern, DiagnosticPattern::MissingReexport);
        assert_eq!(d.severity, Severity::Info);
        assert_eq!(d.confidence, Confidence::Moderate);
        assert!(!d.evidence.is_empty());
        assert!(d.suggestion.contains("helper_b"));
    }

