#[test]
fn test_rust_chained_method_calls_no_crash() {
    let source = r#"
fn process(data: Vec<i32>) -> Vec<i32> {
    data.iter().map(|x| x + 1).collect()
}
"#;
    let (graph, _) = parse_and_populate_rust(source);
    let (process_id, _) = find_symbol(&graph, "process");

