        SymbolKind::Module,
        Visibility::Public,
        "src/empty_parent/mod.rs",
        1,
    ));
    // Import referencing a child of the empty parent
    let _import = graph.add_symbol(make_from_import_c18(
        "child",
        "crate::empty_parent",
        "src/consumer.rs",
        1,
    ));
    let module_map = build_module_map(&[
