fn test_c20_t12_circular_dep_type_checking_only_cycle_question() {
    let mut graph = Graph::new();

    // Both files import each other ONLY inside TYPE_CHECKING blocks
    let func_a = graph.add_symbol(make_symbol(
        "ClassA",
        SymbolKind::Class,
        Visibility::Public,
