    add_ref(&mut graph, imp_ba, func_a, ReferenceKind::Import, "b.py");

    let results = circular_dependency::detect(&graph, Path::new(""));
    // DESIGN DECISION: If TYPE_CHECKING-aware filtering is implemented in the
