        s.annotations.push("from:a".to_string());
        s
    });
    add_ref(
        &mut graph,
        reexport_b,
        func_a,
        ReferenceKind::Export,
        "b.py",
    );

    // b.py has its own function used by a.py
    let func_b = graph.add_symbol(make_symbol(
        "helper_fn",
        SymbolKind::Function,
        Visibility::Public,
        "b.py",
        10,
    ));
    let imp_ab = graph.add_symbol({
