        );
    }

    #[test]
    fn json_formatter_escapes_special_characters() {
        let mut manifest = Manifest::empty();
        manifest.metadata.project = r#"project "with" quotes & back\slashes"#.to_string();
        manifest.entities.push(EntityEntry {
            id: "module::func_with_\"quotes\"".to_string(),
            kind: "fn".to_string(),
            vis: "pub".to_string(),
            sig: "() -> str".to_string(),
            loc: r"src\path\file.py:1".to_string(),
            calls: vec![],
            called_by: vec![],
            annotations: vec![],
        });

        let formatter = JsonFormatter::new();
        let json = formatter.format_manifest(&manifest).unwrap();

        let parsed: Result<serde_json::Value, _> = serde_json::from_str(&json);
        assert!(
            parsed.is_ok(),
            "Special characters produced invalid JSON: {:?}\nJSON:\n{}",
            parsed.err(),
            &json[..json.len().min(500)]
        );

        let val = parsed.unwrap();
        assert!(val["metadata"]["project"]
            .as_str()
            .unwrap()
            .contains("quotes"));
    }

    #[test]
    fn json_evidence_none_fields_omitted_not_null() {
        let diagnostics = vec![DiagnosticEntry {
            id: "D001".to_string(),
            pattern: "test".to_string(),
            severity: "warning".to_string(),
            confidence: "high".to_string(),
            entity: "test::fn".to_string(),
            message: "test".to_string(),
            evidence: vec![EvidenceEntry {
                observation: "test observation".to_string(),
                location: None,
                context: None,
            }],
            suggestion: "test".to_string(),
            loc: "test.py:1".to_string(),
        }];

        let formatter = JsonFormatter::new();
        let json = formatter.format_diagnostics(&diagnostics).unwrap();
        let parsed: serde_json::Value = serde_json::from_str(&json).unwrap();

        let evidence = &parsed[0]["evidence"][0];
        assert!(
            evidence.get("observation").is_some(),
            "observation must be present"
        );
        assert!(
            evidence.get("location").is_none(),
            "None location must be OMITTED from JSON, not present as null. Got: {:?}",
            evidence.get("location")
        );
        assert!(
            evidence.get("context").is_none(),
            "None context must be OMITTED from JSON, not present as null. Got: {:?}",
            evidence.get("context")
        );
    }

    #[test]
    fn json_serde_rename_attributes_applied() {
        let manifest = Manifest::sample_full();
        let formatter = JsonFormatter::new();
        let json = formatter.format_manifest(&manifest).unwrap();

        let parsed: serde_json::Value = serde_json::from_str(&json).unwrap();
        assert!(parsed.is_object(), "Root must be an object");

        if let Some(boundaries) = parsed["boundaries"].as_array() {
            for boundary in boundaries {
                assert!(
                    boundary.get("type").is_some(),
                    "BoundaryEntry must use 'type' not 'boundary_type' in JSON"
                );
                assert!(
                    boundary.get("boundary_type").is_none(),
                    "BoundaryEntry must not expose Rust field name 'boundary_type'"
                );
            }
        }
    }

    #[test]
    fn json_roundtrip_manifest() {
        let original = Manifest::sample_full();
        let formatter = JsonFormatter::new();
        let json = formatter.format_manifest(&original).unwrap();

        let deserialized: Manifest =
            serde_json::from_str(&json).expect("JSON output must deserialize back to Manifest");

        assert_eq!(deserialized.metadata.project, original.metadata.project);
        assert_eq!(deserialized.entities.len(), original.entities.len());
        assert_eq!(deserialized.diagnostics.len(), original.diagnostics.len());
        assert_eq!(deserialized.flows.len(), original.flows.len());
    }
}

//! Manifest output formatting — the final stage of the Flowspec pipeline.
//!
//! The manifest module owns the output contract: what format the analysis
//! results take when written to stdout or a file. [`OutputFormatter`] is one
//! of two sanctioned traits (per `conventions.yaml`) — one implementation per
//! output format (YAML, JSON, SARIF, summary). The graph is the source of
//! truth; manifests are exports of it.
//!
//! **Pipeline position:** Parser → Graph → Analyzer → Manifest.
//! Input comes from [`crate::analyzer`] diagnostics and [`crate::graph::Graph`]
//! queries. Output is validated by [`validate_manifest_size`] to enforce
//! format-specific source-size constraints (with a 20KB floor for small projects).

/// JSON output formatter.
pub mod json;
/// SARIF v2.1.0 output formatter for CI integration.
pub mod sarif;
/// Human-readable summary output formatter (~2K tokens).
pub mod summary;
/// Manifest data types — `Manifest`, `EntityEntry`, `FlowEntry`, `DiagnosticEntry`, etc.
pub mod types;
/// YAML output formatter (default format).
pub mod yaml;

pub use json::JsonFormatter;
pub use sarif::SarifFormatter;
pub use summary::SummaryFormatter;
pub use types::*;
pub use yaml::YamlFormatter;

use crate::error::ManifestError;

/// Minimum source bytes before the 10x size limit is enforced.
///
/// Small projects have disproportionate metadata overhead, so the
/// manifest-to-source ratio naturally exceeds 10x for tiny inputs.
/// Below this threshold, the size check is skipped.
const SIZE_CHECK_MIN_SOURCE_BYTES: u64 = 1024;

/// Maximum allowed ratio of manifest bytes to source bytes (YAML/default).
///
/// Format-specific thresholds are computed by [`max_ratio_for_format`].
/// This constant is the baseline for YAML and unknown formats.
const SIZE_CHECK_MAX_RATIO: f64 = 10.0;

/// Returns the maximum allowed manifest-to-source ratio for a given output format.
///
/// Different formats have inherent overhead that affects the ratio:
/// - **YAML** (10x): Most compact structured format. Baseline limit.
/// - **JSON** (15x): ~1.2-1.5x overhead from braces, quotes, commas.
/// - **SARIF** (20x): ~1.3-1.8x overhead from rule metadata, result objects, tool info.
/// - **Summary**: Exempt — always small (~2K tokens), no meaningful ratio risk.
/// - **Unknown** (10x): Strictest limit as fail-safe for unrecognized format strings.
fn max_ratio_for_format(format: &str) -> f64 {
    match format {
        "json" => 15.0,
        "sarif" => 20.0,
        "summary" => f64::MAX,
        _ => SIZE_CHECK_MAX_RATIO, // yaml and unknown formats use strictest limit
    }
}

/// Minimum manifest size (in bytes) that is always allowed regardless of ratio.
///
/// Manifests under 20KB are small enough that they pose no risk of overwhelming
/// AI agent consumers, even if their ratio to source code exceeds 10x. This
/// protects small projects with high metadata overhead from spurious rejections.
const MIN_MANIFEST_ALLOW_BYTES: u64 = 20_480;

/// Validates that a serialized manifest does not exceed the format-specific source size limit.
///
/// The spec constraint (`constraints.yaml:36,48`) mandates that manifests must not
/// exceed a format-dependent multiple of the source code size. This prevents bloated
/// output that overwhelms AI agent consumers.
///
/// Per-format thresholds account for inherent format overhead:
/// - YAML: 10x (most compact, baseline)
/// - JSON: 15x (braces, quotes, commas add ~1.2-1.5x)
/// - SARIF: 20x (rule metadata, result objects, tool info add ~1.3-1.8x)
/// - Summary: exempt (always small)
///
/// Returns `Ok(())` if the size is acceptable, or `Err(ManifestError::SizeLimit)` if
/// the manifest exceeds the limit. Skips the check when:
/// - `source_bytes` is below [`SIZE_CHECK_MIN_SOURCE_BYTES`] (tiny projects)
/// - manifest size is below [`MIN_MANIFEST_ALLOW_BYTES`] (small manifests always allowed)
pub fn validate_manifest_size(
    serialized: &str,
    source_bytes: u64,
    format: &str,
) -> Result<(), ManifestError> {
    if source_bytes < SIZE_CHECK_MIN_SOURCE_BYTES {
        return Ok(());
    }

    let manifest_bytes = serialized.len() as u64;

    if manifest_bytes < MIN_MANIFEST_ALLOW_BYTES {
        return Ok(());
    }

    let ratio = manifest_bytes as f64 / source_bytes as f64;
    let limit = max_ratio_for_format(format);

    if ratio > limit {
        return Err(ManifestError::SizeLimit {
            manifest_bytes,
            source_bytes,
            ratio,
            limit,
        });
    }

    Ok(())
}

/// Trait for formatting analysis output. One implementation per output format.
///
/// This is one of two sanctioned traits in Flowspec (per `conventions.yaml`).
/// Each output format — YAML, JSON, SARIF, summary — has exactly one
/// implementation. To add a new output format, implement this trait and
/// register the formatter in `commands.rs`.
///
/// # Implementors
///
/// - [`YamlFormatter`] — default format, full manifest (agents).
/// - [`JsonFormatter`] — full manifest for tooling consumers.
/// - [`SarifFormatter`] — SARIF v2.1.0 for CI integration (GitHub Code Scanning).
/// - [`SummaryFormatter`] — compact plain-text (~2K tokens, humans).
///
/// # Contract
///
/// - `format_manifest` must produce valid, parseable output in the target format.
/// - `format_diagnostics` formats the filtered subset used by the `diagnose` command.
/// - Implementations must not alter the ordering of manifest sections.
pub trait OutputFormatter {
    /// Format a complete [`Manifest`] into a string (for the `analyze` command).
    fn format_manifest(&self, manifest: &Manifest) -> Result<String, ManifestError>;

    /// Format only diagnostics into a string (for the `diagnose` command).
    fn format_diagnostics(&self, diagnostics: &[DiagnosticEntry]) -> Result<String, ManifestError>;
}

//! SARIF v2.1.0 output formatter — produces valid SARIF JSON for GitHub Code Scanning.
//!
//! SARIF (Static Analysis Results Interchange Format) is the standard format
//! for static analysis tools integrating with GitHub Code Scanning and other
//! CI systems. This formatter maps Flowspec diagnostics to SARIF results with
//! rule definitions, severity levels, and physical locations.

use serde::Serialize;

use crate::error::ManifestError;
use crate::manifest::{DiagnosticEntry, Manifest, OutputFormatter};

/// SARIF schema URL for v2.1.0.
const SARIF_SCHEMA: &str =
    "https://raw.githubusercontent.com/oasis-tcs/sarif-spec/main/sarif-2.1/schema/sarif-schema-2.1.0.json";

/// SARIF version string.
const SARIF_VERSION: &str = "2.1.0";

// --- SARIF schema structs ---

/// Top-level SARIF log object.
#[derive(Debug, Serialize)]
struct SarifLog {
    #[serde(rename = "$schema")]
    schema: String,
    version: String,
    runs: Vec<Run>,
}

/// A single analysis run.
#[derive(Debug, Serialize)]
struct Run {
    tool: Tool,
    results: Vec<SarifResult>,
}

/// Tool metadata.
#[derive(Debug, Serialize)]
struct Tool {
    driver: ToolDriver,
}

/// Tool driver (the analysis tool itself).
#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
struct ToolDriver {
    name: String,
    version: String,
    information_uri: String,
    rules: Vec<Rule>,
}

/// A rule definition (maps to a diagnostic pattern).
#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
struct Rule {
    id: String,
    short_description: Message,
}

/// A SARIF result (maps to a single diagnostic finding).
#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
struct SarifResult {
    rule_id: String,
    level: String,
    message: Message,
    locations: Vec<Location>,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    related_locations: Vec<RelatedLocation>,
}

/// A message object with text content.
#[derive(Debug, Serialize)]
struct Message {
    text: String,
}

/// A physical location in the source code.
#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
struct Location {
    physical_location: PhysicalLocation,
}

/// Physical location details (file + region).
#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
struct PhysicalLocation {
    artifact_location: ArtifactLocation,
    #[serde(skip_serializing_if = "Option::is_none")]
    region: Option<Region>,
}

/// File path as a URI.
#[derive(Debug, Serialize)]
struct ArtifactLocation {
    uri: String,
}

/// Source region (line number).
#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
struct Region {
    start_line: u64,
}

/// A related location (maps to evidence entries with locations).
#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
struct RelatedLocation {
    id: usize,
    physical_location: PhysicalLocation,
    message: Message,
}

// --- Helpers ---

/// Map Flowspec severity to SARIF level.
///
/// - critical → error
/// - warning → warning
/// - info → note
/// - unknown → warning (safe default)
pub fn severity_to_level(severity: &str) -> &'static str {
    match severity {
        "critical" => "error",
        "warning" => "warning",
        "info" => "note",
        _ => "warning",
    }
}

/// Parse a location string "file:line" into (file, optional line number).
///
/// Splits on the last `:` to handle paths that may contain colons.
/// Returns the full string as the file if no valid line number is found.
pub fn parse_location(loc: &str) -> (&str, Option<u64>) {
    if loc.is_empty() {
        return ("", None);
    }
    if let Some(colon_pos) = loc.rfind(':') {
        let (file_part, line_part) = loc.split_at(colon_pos);
        // line_part starts with ':', skip it
        if let Ok(line) = line_part[1..].parse::<u64>() {
            return (file_part, Some(line));
        }
    }
    (loc, None)
}

/// Build deduplicated rule definitions from diagnostic entries.
///
/// Each unique `pattern` in the diagnostics becomes one rule entry.
fn build_rules(diagnostics: &[DiagnosticEntry]) -> Vec<Rule> {
    let mut seen = std::collections::HashSet::new();
    let mut rules = Vec::new();
    for diag in diagnostics {
        if seen.insert(diag.pattern.clone()) {
            rules.push(Rule {
                id: diag.pattern.clone(),
                short_description: Message {
                    text: diag.pattern.replace('_', " "),
                },
            });
        }
    }
    rules
}

/// Convert a single diagnostic entry to a SARIF result.
fn diagnostic_to_result(diag: &DiagnosticEntry) -> SarifResult {
    let (file, line) = parse_location(&diag.loc);
    let location = Location {
        physical_location: PhysicalLocation {
            artifact_location: ArtifactLocation {
                uri: file.to_string(),
            },
            region: line.map(|l| Region { start_line: l }),
        },
    };

    // Map evidence entries with locations to relatedLocations
    let related_locations: Vec<RelatedLocation> = diag
        .evidence
        .iter()
        .enumerate()
        .filter_map(|(i, ev)| {
            ev.location.as_ref().map(|loc_str| {
                let (ev_file, ev_line) = parse_location(loc_str);
                RelatedLocation {
                    id: i + 1,
                    physical_location: PhysicalLocation {
                        artifact_location: ArtifactLocation {
                            uri: ev_file.to_string(),
                        },
                        region: ev_line.map(|l| Region { start_line: l }),
                    },
                    message: Message {
                        text: ev.observation.clone(),
                    },
                }
            })
        })
        .collect();

    SarifResult {
        rule_id: diag.pattern.clone(),
        level: severity_to_level(&diag.severity).to_string(),
        message: Message {
            text: diag.message.clone(),
        },
        locations: vec![location],
        related_locations,
    }
}

/// Build a complete SARIF log from a slice of diagnostics.
fn build_sarif_log(diagnostics: &[DiagnosticEntry]) -> SarifLog {
    let rules = build_rules(diagnostics);
    let results: Vec<SarifResult> = diagnostics.iter().map(diagnostic_to_result).collect();

    SarifLog {
        schema: SARIF_SCHEMA.to_string(),
        version: SARIF_VERSION.to_string(),
        runs: vec![Run {
            tool: Tool {
                driver: ToolDriver {
                    name: "Flowspec".to_string(),
                    version: env!("CARGO_PKG_VERSION").to_string(),
                    information_uri: "https://github.com/Mzzkc/flowspec".to_string(),
                    rules,
                },
            },
            results,
        }],
    }
}

// --- Formatter ---

/// SARIF v2.1.0 formatter for manifest and diagnostic output.
///
/// Produces JSON conforming to the SARIF v2.1.0 specification, suitable for
/// upload to GitHub Code Scanning, Azure DevOps, and other SARIF consumers.
/// Maps each Flowspec diagnostic to a SARIF result with rule definition,
/// severity level, physical location, and related locations from evidence.
pub struct SarifFormatter;

impl SarifFormatter {
    /// Create a new SARIF formatter.
    pub fn new() -> Self {
        Self
    }
}

impl Default for SarifFormatter {
    fn default() -> Self {
        Self::new()
    }
}

impl OutputFormatter for SarifFormatter {
    fn format_manifest(&self, manifest: &Manifest) -> Result<String, ManifestError> {
        let sarif = build_sarif_log(&manifest.diagnostics);
        serde_json::to_string_pretty(&sarif).map_err(|e| ManifestError::Serialization {
            reason: e.to_string(),
        })
    }

    fn format_diagnostics(&self, diagnostics: &[DiagnosticEntry]) -> Result<String, ManifestError> {
        let sarif = build_sarif_log(diagnostics);
        serde_json::to_string_pretty(&sarif).map_err(|e| ManifestError::Serialization {
            reason: e.to_string(),
        })
    }
}

