            .as_str()
            .unwrap();
        assert_eq!(version, env!("CARGO_PKG_VERSION"));
    }
}

//! Summary output formatter — compact, token-efficient text output.
//!
//! Produces a ~2K token plain-text summary of analysis results.
//! Designed for quick consumption by humans and AI agents who need
//! structural understanding without the full manifest.

use crate::error::ManifestError;
use crate::manifest::{DiagnosticEntry, Manifest, OutputFormatter};

/// Summary formatter for manifest and diagnostic output.
///
/// Produces plain-text output with aligned sections and counts.
/// Target budget: ~2K tokens (~8KB text) for typical projects.
pub struct SummaryFormatter;

impl SummaryFormatter {
    /// Create a new summary formatter.
    pub fn new() -> Self {
        Self
    }
}

impl Default for SummaryFormatter {
    fn default() -> Self {
        Self::new()
    }
}

impl OutputFormatter for SummaryFormatter {
    fn format_manifest(&self, manifest: &Manifest) -> Result<String, ManifestError> {
        let mut lines = Vec::new();

        // Header
        lines.push(format!("Flowspec Analysis: {}", manifest.metadata.project));
        lines.push(format!(
            "Version: {} | Analyzed: {}",
            manifest.metadata.flowspec_version, manifest.metadata.analyzed_at
        ));
        lines.push(String::new());

        // Counts
        lines.push("--- Overview ---".to_string());
        lines.push(format!(
            "Files: {}  Entities: {}  Flows: {}  Diagnostics: {}",
            manifest.metadata.file_count,
            manifest.metadata.entity_count,
            manifest.metadata.flow_count,
            manifest.metadata.diagnostic_count
        ));
        if !manifest.metadata.languages.is_empty() {
            lines.push(format!(
                "Languages: {}",
                manifest.metadata.languages.join(", ")
            ));
        }
        lines.push(String::new());

        // Architecture
        if !manifest.summary.architecture.is_empty() {
            lines.push("--- Architecture ---".to_string());
            lines.push(manifest.summary.architecture.clone());
            lines.push(String::new());
        }

        // Diagnostics summary
        let ds = &manifest.summary.diagnostic_summary;
        if ds.critical > 0 || ds.warning > 0 || ds.info > 0 {
            lines.push("--- Diagnostics ---".to_string());
            lines.push(format!(
                "Critical: {}  Warning: {}  Info: {}",
                ds.critical, ds.warning, ds.info
            ));
            if !ds.top_issues.is_empty() {
                lines.push(String::new());
                lines.push("Top issues:".to_string());
                for (i, issue) in ds.top_issues.iter().take(5).enumerate() {
                    lines.push(format!("  {}. {}", i + 1, issue));
                }
            }
            lines.push(String::new());
        }

        // Modules (sorted by entity_count desc, max 10)
        if !manifest.summary.modules.is_empty() {
            lines.push("--- Modules ---".to_string());
            for module in manifest.summary.modules.iter().take(10) {
                lines.push(format!(
                    "  {} ({} entities) — {}",
                    module.name, module.entity_count, module.role
                ));
            }
            if manifest.summary.modules.len() > 10 {
                lines.push(format!(
                    "  ... and {} more",
                    manifest.summary.modules.len() - 10
                ));
            }
            lines.push(String::new());
        }

        // Entry points
        if !manifest.summary.entry_points.is_empty() {
            lines.push("--- Entry Points ---".to_string());
            for ep in &manifest.summary.entry_points {
                lines.push(format!("  {}", ep));
            }
            lines.push(String::new());
        }

        // Findings list (max 10)
        if !manifest.diagnostics.is_empty() {
            lines.push("--- Findings ---".to_string());
            for diag in manifest.diagnostics.iter().take(10) {
                lines.push(format!(
                    "  [{}] {} — {} ({})",
                    diag.severity.to_uppercase(),
                    diag.pattern,
                    diag.message,
                    diag.loc
                ));
            }
            if manifest.diagnostics.len() > 10 {
                lines.push(format!(
                    "  ... and {} more findings",
                    manifest.diagnostics.len() - 10
                ));
            }
            lines.push(String::new());
        }

        Ok(lines.join("\n"))
    }

    fn format_diagnostics(&self, diagnostics: &[DiagnosticEntry]) -> Result<String, ManifestError> {
        let mut lines = Vec::new();

        lines.push(format!("Diagnostics: {} finding(s)", diagnostics.len()));
        lines.push(String::new());

        if diagnostics.is_empty() {
            lines.push("No findings.".to_string());
            return Ok(lines.join("\n"));
        }

        // Count by severity
        let critical = diagnostics
            .iter()
            .filter(|d| d.severity == "critical")
            .count();
        let warning = diagnostics
            .iter()
            .filter(|d| d.severity == "warning")
            .count();
        let info = diagnostics.iter().filter(|d| d.severity == "info").count();

        lines.push(format!(
            "Critical: {}  Warning: {}  Info: {}",
            critical, warning, info
        ));
        lines.push(String::new());

        for diag in diagnostics {
            lines.push(format!(
                "[{}] {} — {} ({})",
                diag.severity.to_uppercase(),
                diag.pattern,
                diag.message,
                diag.loc
            ));
            if !diag.suggestion.is_empty() {
                lines.push(format!("  Fix: {}", diag.suggestion));
            }
        }

        Ok(lines.join("\n"))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn summary_formatter_produces_output_for_full_manifest() {
        let manifest = Manifest::sample_full();
        let formatter = SummaryFormatter::new();
        let result = formatter.format_manifest(&manifest);
        assert!(result.is_ok(), "Summary format failed: {:?}", result.err());

        let output = result.unwrap();
        assert!(!output.is_empty());
        assert!(output.contains("Flowspec Analysis:"));
        assert!(output.contains("test-project"));
    }

    #[test]
    fn summary_formatter_produces_output_for_empty_manifest() {
        let manifest = Manifest::empty();
        let formatter = SummaryFormatter::new();
        let result = formatter.format_manifest(&manifest);
        assert!(
            result.is_ok(),
            "Empty manifest summary failed: {:?}",
            result.err()
        );

        let output = result.unwrap();
        assert!(!output.is_empty());
        // Must have overview section even for empty project
        assert!(output.contains("Files: 0"));
    }

    #[test]
    fn summary_output_size_bounded() {
        let manifest = Manifest::sample_full();
        let formatter = SummaryFormatter::new();
        let output = formatter.format_manifest(&manifest).unwrap();

        // Must be bounded (~2K tokens ≈ ~8KB). Allow generous 16KB.
        assert!(
            output.len() < 16_384,
            "Summary output too large: {} bytes",
            output.len()
        );
        assert!(
            output.len() > 50,
            "Summary output suspiciously small: {} bytes",
            output.len()
        );
    }

    #[test]
    fn summary_contains_key_sections() {
        let manifest = Manifest::sample_full();
        let formatter = SummaryFormatter::new();
        let output = formatter.format_manifest(&manifest).unwrap();

        assert!(
            output.contains("File") || output.contains("file"),
            "Summary must mention files"
        );
        assert!(
            output.contains("Entit") || output.contains("entit"),
            "Summary must mention entities"
        );
        assert!(
            output.contains("Diagnostic")
                || output.contains("diagnostic")
                || output.contains("Finding")
                || output.contains("finding"),
            "Summary must mention diagnostics/findings"
        );
    }

    #[test]
    fn summary_format_diagnostics_works() {
        let diagnostics = vec![
            DiagnosticEntry::sample_critical(),
            DiagnosticEntry::sample_warning(),
        ];
        let formatter = SummaryFormatter::new();
        let result = formatter.format_diagnostics(&diagnostics);
        assert!(result.is_ok());

        let output = result.unwrap();
        assert!(output.contains("2 finding(s)"));
        assert!(output.contains("Critical: 1"));
    }

    #[test]
    fn summary_format_empty_diagnostics() {
        let diagnostics: Vec<DiagnosticEntry> = vec![];
        let formatter = SummaryFormatter::new();
        let result = formatter.format_diagnostics(&diagnostics);
        assert!(result.is_ok());

        let output = result.unwrap();
        assert!(output.contains("0 finding(s)"));
        assert!(output.contains("No findings"));
    }
}

//! Manifest data model — all 8 required sections per manifest-schema.yaml.
//!
//! Field names use abbreviated forms (vis, sig, loc) for token efficiency.
//! Structs are ordered so serde_yaml serializes sections in priority order:
//! metadata → summary → diagnostics → entities → flows → boundaries →
//! dependency_graph → type_flows (most valuable first).

use serde::{Deserialize, Serialize};

/// Complete analysis manifest — the primary output of `flowspec analyze`.
///
/// Contains all 8 required sections. Sections are always present even when
/// empty (empty lists, not omitted) so consumers can rely on a stable schema.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Manifest {
    /// Project identity, analysis timestamp, version, counts.
    pub metadata: Metadata,
    /// Compressed structural overview (~2K token budget).
    pub summary: Summary,
    /// Structural issues found in the codebase.
    pub diagnostics: Vec<DiagnosticEntry>,
    /// Every meaningful symbol in the codebase.
    pub entities: Vec<EntityEntry>,
    /// Traced data flow paths from entry to exit.
    pub flows: Vec<FlowEntry>,
    /// Interfaces where data crosses a meaningful boundary.
    pub boundaries: Vec<BoundaryEntry>,
    /// Module-level dependency structure.
    pub dependency_graph: Vec<DependencyEdge>,
    /// Where each significant type is created, transformed, and consumed.
    pub type_flows: Vec<TypeFlowEntry>,
}

/// Project identity, analysis timestamp, version, and aggregate counts.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Metadata {
    /// Project name (derived from directory name or config).
    pub project: String,
    /// ISO 8601 timestamp of when analysis was performed.
    pub analyzed_at: String,
    /// Flowspec version that produced this manifest.
    pub flowspec_version: String,
    /// Languages detected and analyzed.
    pub languages: Vec<String>,
    /// Total number of files analyzed.
    pub file_count: u64,
    /// Total number of entities found.
    pub entity_count: u64,
    /// Total number of flows traced.
    pub flow_count: u64,
    /// Total number of diagnostics reported.
    pub diagnostic_count: u64,
    /// Whether this was an incremental analysis.
    pub incremental: bool,
    /// Number of files re-analyzed (0 if full run).
    pub files_changed: u64,
}

/// Compressed structural overview. An agent reading only this section
/// should understand the project's architecture, key flows, and issues.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Summary {
    /// 2-4 sentence description of the project's structure.
    pub architecture: String,
    /// Each module with count and one-line role description.
    pub modules: Vec<ModuleSummary>,
    /// Where data enters the system.
    pub entry_points: Vec<String>,
    /// Where data leaves the system.
    pub exit_points: Vec<String>,
    /// The most significant data flow paths, compressed.
    pub key_flows: Vec<KeyFlow>,
    /// Diagnostic counts by severity plus top issues.
    pub diagnostic_summary: DiagnosticSummary,
}

/// A module's summary entry.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ModuleSummary {
    /// Module name.
    pub name: String,
    /// Number of entities in this module.
    pub entity_count: u64,
    /// One-line role description.
    pub role: String,
}

/// A key data flow path summary.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct KeyFlow {
    /// Flow name.
    pub name: String,
    /// Compressed path summary.
    pub path_summary: String,
}

/// Diagnostic counts by severity plus top issues as one-liners.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DiagnosticSummary {
    /// Number of critical diagnostics.
    pub critical: u64,
    /// Number of warning diagnostics.
    pub warning: u64,
    /// Number of info diagnostics.
    pub info: u64,
    /// Top issues as one-line summaries (max 5).
    pub top_issues: Vec<String>,
}

/// A single entity (symbol) entry using abbreviated field names.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EntityEntry {
    /// Unique identifier: module_path::name.
    pub id: String,
    /// Symbol kind: fn, method, struct, class, trait, interface, module, var, const, macro, enum.
    pub kind: String,
    /// Visibility: pub, priv, crate, protected.
    pub vis: String,
    /// Compact signature: (param_types) -> return_type.
    pub sig: String,
    /// Location: file:line.
    pub loc: String,
    /// IDs of symbols this entity calls.
    pub calls: Vec<String>,
    /// IDs of symbols that call this entity.
    pub called_by: Vec<String>,
    /// Decorators, derives, attributes.
    pub annotations: Vec<String>,
}

/// A single piece of evidence supporting a diagnostic finding.
///
/// Mirrors `analyzer::diagnostic::Evidence` in the manifest namespace.
/// Uses `skip_serializing_if` to keep YAML clean when optional fields are absent.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct EvidenceEntry {
    /// What Flowspec observed.
    pub observation: String,
    /// Source location relevant to this observation (e.g., "src/utils.py:42").
    #[serde(skip_serializing_if = "Option::is_none")]
    pub location: Option<String>,
    /// Additional context about the observation.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub context: Option<String>,
}

/// A single diagnostic entry with all required fields including confidence.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DiagnosticEntry {
    /// Unique diagnostic ID (D001, D002, ...).
    pub id: String,
    /// Failure pattern category.
    pub pattern: String,
    /// Severity: critical, warning, info.
    pub severity: String,
    /// Confidence level: high, moderate, low.
    pub confidence: String,
    /// Primary entity or entities involved.
    pub entity: String,
    /// Human/agent-readable description of the issue.
    pub message: String,
    /// Structured evidence — what Flowspec observed to support this diagnostic.
    pub evidence: Vec<EvidenceEntry>,
    /// Actionable fix suggestion.
    pub suggestion: String,
    /// Primary file:line location.
    pub loc: String,
}

/// A traced data flow path from entry point to exit point.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FlowEntry {
    /// Flow identifier.
    pub id: String,
    /// One-line summary of what this flow does.
    pub description: String,
    /// Entry point entity ID.
    pub entry: String,
    /// Exit point entity ID or description.
    pub exit: String,
    /// Ordered steps in the flow.
    pub steps: Vec<FlowStep>,
    /// Diagnostic IDs that affect this flow.
    pub issues: Vec<String>,
}

/// A single step in a data flow.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FlowStep {
    /// Entity involved in this step.
    pub entity: String,
    /// Action performed.
    pub action: String,
    /// Input type.
    pub in_type: String,
    /// Output type.
    pub out_type: String,
}

/// A boundary where data crosses a meaningful interface.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BoundaryEntry {
    /// Boundary identifier.
    pub id: String,
    /// Boundary type: module, package, network, serialization, ffi.
    #[serde(rename = "type")]
    pub boundary_type: String,
    /// Source module/scope.
    pub from: String,
    /// Target module/scope.
    pub to: String,
    /// Functions that cross this boundary.
    pub crossing_points: Vec<CrossingPoint>,
    /// Diagnostic IDs at this boundary.
    pub issues: Vec<String>,
}

/// A function that crosses a boundary.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CrossingPoint {
    /// Function name.
    #[serde(rename = "fn")]
    pub func: String,
    /// Data type flowing in.
    pub data_in: String,
    /// Data type flowing out.
    pub data_out: String,
}

/// A module-level dependency edge.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DependencyEdge {
    /// Source module.
    pub from: String,
    /// Target module.
    pub to: String,
    /// Number of cross-references.
    pub weight: u64,
    /// Direction: unidirectional or bidirectional.
    pub direction: String,
    /// Diagnostic IDs (e.g., circular deps).
    pub issues: Vec<String>,
}

/// Where a significant type is created, transformed, and consumed.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TypeFlowEntry {
    /// Type name.
    #[serde(rename = "type")]
    pub type_name: String,
    /// Where instances are created.
    pub created_at: Vec<String>,
    /// How this type is transformed.
    pub transformed_to: Vec<TypeTransformation>,
    /// Where this type is consumed.
    pub consumed_by: Vec<String>,
    /// Scope: request, session, static, etc.
    pub lifetime: String,
}

/// A type transformation step.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TypeTransformation {
    /// Target type after transformation.
    pub target_type: String,
    /// Function/method that performs the transformation.
    pub via: String,
}

impl Manifest {
    /// Create an empty manifest with all sections present but unpopulated.
    pub fn empty() -> Self {
        Self {
            metadata: Metadata {
                project: String::new(),
                analyzed_at: String::new(),
                flowspec_version: String::new(),
                languages: Vec::new(),
                file_count: 0,
                entity_count: 0,
                flow_count: 0,
