    // Must find entities from isolated_module.py
    assert!(
        entity_names.iter().any(|n| n.contains("process")),
        "Must find process from isolated_module.py. Entities: {:?}",
        entity_names
    );

    // Must find entities from clean_code.py
    assert!(
