#[test]
fn manifest_does_not_exceed_10x_source_size() {
    let project = create_project_with_issues();
    let source_size: u64 = walkdir::WalkDir::new(project.path())
        .into_iter()
        .filter_map(|e| e.ok())
        .filter(|e| e.path().extension().map(|x| x == "py").unwrap_or(false))
        .map(|e| e.metadata().map(|m| m.len()).unwrap_or(0))
        .sum();

    let mut cmd = Command::cargo_bin("flowspec").unwrap();
    let output = cmd
        .args(["analyze", project.path().to_str().unwrap()])
        .output()
        .unwrap();

    let manifest_size = output.stdout.len() as u64;
    // For very small fixtures, the manifest has fixed overhead (metadata, summary
    // structure) that inflates the ratio. The 10x constraint targets real projects
    // (50K LOC → 500KB). Use a floor of 1KB to avoid false positives on tiny fixtures.
    let effective_source = source_size.max(1024);
    assert!(
        manifest_size <= effective_source * 10,
        "Manifest size ({} bytes) exceeds 10x source size ({} bytes). Ratio: {:.1}x",
        manifest_size,
        source_size,
        manifest_size as f64 / source_size as f64
    );
}

